const std=@import("std");const s=@import("support.zig");pub fn batch(a:std.mem.Allocator,state:*std.StringHashMap(i64),ops:[]s.V)![]const u8{var staged=try state.cloneWithAllocator(a);var status:[]const u8="committed";for(ops)|x|{const from=try s.id(s.get(x,"from"));const to=try s.id(s.get(x,"to"));const n=try s.integer(s.get(x,"amount"),0,1000000);const source=staged.get(from) orelse {status="unknown-account";break;};const target=staged.get(to) orelse {status="unknown-account";break;};if(source<n){status="insufficient";break;}if(!std.mem.eql(u8,from,to)){try staged.put(from,source-n);try staged.put(to,target+n);}}state.*=staged;return status;}
